{
  "decisions": [
    {
      "requirement_id": "AI-001",
      "methods": [
        "Test"
      ],
      "rationale": "The behavior of returning a single category and a confidence score within the specified range is verified by submitting documents and observing the system's output."
    },
    {
      "requirement_id": "AI-002",
      "methods": [
        "Analiz"
      ],
      "rationale": "Achieving a specific macro-averaged F1 score requires statistical evaluation and calculation on a held-out dataset."
    },
    {
      "requirement_id": "AI-003",
      "methods": [
        "Test"
      ],
      "rationale": "The routing logic for low-confidence documents is verified by submitting documents with known low confidence scores and observing the destination queue."
    },
    {
      "requirement_id": "AI-004",
      "methods": [
        "Test"
      ],
      "rationale": "Performance under specific load conditions is verified by executing the system with the defined request rate and measuring response times."
    },
    {
      "requirement_id": "AI-005",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The presence and correctness of recorded metadata (model version, hash, category) are verified by inspecting the log entries or database records."
    },
    {
      "requirement_id": "AI-006",
      "methods": [
        "Analiz"
      ],
      "rationale": "Detecting distribution deviation using the population stability index requires statistical analysis of the weekly prediction data against a baseline."
    },
    {
      "requirement_id": "AI-007",
      "methods": [
        "Test"
      ],
      "rationale": "The provision of top contributing text passages is verified by submitting a document and observing the returned explanation data."
    },
    {
      "requirement_id": "AI-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Comparing recall metrics between different language subsets requires statistical analysis of the model's performance on segmented data."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "MED-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by executing the application to create a record and observing that the specified fields are accepted and stored."
    },
    {
      "requirement_id": "MED-002",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The distinct colour display for each triage category is verified by running the application and visually observing the UI elements without performing complex measurements."
    },
    {
      "requirement_id": "MED-003",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by inputting vital signs within and outside the defined ranges and observing the acceptance or rejection behavior of the system."
    },
    {
      "requirement_id": "MED-004",
      "methods": [
        "Test"
      ],
      "rationale": "The offline functionality and local storage capacity are verified by disconnecting the network, creating 500 records, and confirming the application remains functional and data is persisted."
    },
    {
      "requirement_id": "MED-005",
      "methods": [
        "Test"
      ],
      "rationale": "The synchronization and conflict resolution logic is verified by simulating conflicting edits, restoring connectivity, and observing that both versions are retained for manual review."
    },
    {
      "requirement_id": "MED-006",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The use of AES-256 encryption is verified by inspecting the code or configuration files to confirm the correct encryption algorithm and key management are implemented."
    },
    {
      "requirement_id": "MED-007",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The operability with surgical gloves is verified by a user wearing gloves interacting with the tablet interface to demonstrate that all functions are accessible and usable."
    },
    {
      "requirement_id": "MED-008",
      "methods": [
        "Test"
      ],
      "rationale": "The battery life requirement is verified by running the application under the defined usage profile and measuring the duration until the battery is depleted."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies a behavioral response (HTTP 401) to a specific input condition (missing/invalid token), which is verified by executing the system with test requests."
    },
    {
      "requirement_id": "SW-002",
      "methods": [
        "Test"
      ],
      "rationale": "Role-based access control and the resulting HTTP 403 response are functional behaviors that must be observed by sending requests with different role credentials."
    },
    {
      "requirement_id": "SW-003",
      "methods": [
        "Test"
      ],
      "rationale": "Rate limiting behavior, including the HTTP 429 status and Retry-After header, is verified by sending a burst of requests exceeding the limit and observing the system's response."
    },
    {
      "requirement_id": "SW-004",
      "methods": [
        "Analiz"
      ],
      "rationale": "Verifying a 99th percentile latency constraint under a specific load requires statistical analysis of performance data collected during load testing or simulation."
    },
    {
      "requirement_id": "SW-005",
      "methods": [
        "Test"
      ],
      "rationale": "The timeout behavior and HTTP 504 response are functional outcomes that can be observed by simulating a slow backend service and checking the gateway's reaction."
    },
    {
      "requirement_id": "SW-006",
      "methods": [
        "Test"
      ],
      "rationale": "The ability to apply configuration changes without restart or request loss is a dynamic behavior that must be demonstrated by modifying settings while traffic is active and observing continuity."
    },
    {
      "requirement_id": "SW-007",
      "methods": [
        "Test"
      ],
      "rationale": "The generation of structured log entries with specific fields is verified by sending requests and inspecting the resulting log output for the required data points."
    },
    {
      "requirement_id": "SW-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Monthly availability is a statistical metric that cannot be verified in a single test run but requires analysis of uptime data over a defined period or reliability modeling."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KK-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gecikme süresi, sistemin çalıştırılması ve sensör girdilerinin verilmesiyle ölçülerek doğrulanabilir."
    },
    {
      "requirement_id": "KK-002",
      "methods": [
        "Test"
      ],
      "rationale": "Yük testi ile 2.000 iz altında ekran yenileme hızının 10 Hz'in üzerinde kalıp kalmadığı gözlemlenebilir."
    },
    {
      "requirement_id": "KK-003",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Operatörün seçtiği izin detaylarını görüntüleyebilmesi, sistemin çalıştırılıp gözlemlenerek gösterilebilir."
    },
    {
      "requirement_id": "KK-004",
      "methods": [
        "Test"
      ],
      "rationale": "Zamanlayıcı mantığı, girdi kesilerek ve zaman geçişi beklenerek davranışsal olarak test edilebilir."
    },
    {
      "requirement_id": "KK-005",
      "methods": [
        "Test"
      ],
      "rationale": "Bölge ihlali senaryosu oluşturularak görsel ve sesli uyarıların tetiklenip tetiklenmediği gözlemlenebilir."
    },
    {
      "requirement_id": "KK-006",
      "methods": [
        "Test"
      ],
      "rationale": "Mesaj gönderimi ve iletim durumu, iki operatör arasında mesajlaşma yapılarak ve gecikme ölçülerek test edilebilir."
    },
    {
      "requirement_id": "KK-007",
      "methods": [
        "Test"
      ],
      "rationale": "Operatör işlemleri gerçekleştirilerek log kayıtlarının zaman damgası ve kullanıcı kimliği ile tutarlı olduğu doğrulanabilir."
    },
    {
      "requirement_id": "KK-008",
      "methods": [
        "Test"
      ],
      "rationale": "Birincil sunucu arızası simüle edilerek yedek sunucunun devralma süresi ve veri bütünlüğü test edilebilir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": [
        "Test"
      ],
      "rationale": "Sistemin e-Devlet entegrasyonu ile oturum açma işlevinin çalışıp çalışmadığı, gerçek bir kullanıcı senaryosu üzerinden sistemin çalıştırılması ve girdi verilerek gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-002",
      "methods": [
        "Test"
      ],
      "rationale": "15 dakikalık inaktivite süresinin sonunda oturumun sonlandırılması ve yönlendirme davranışının, zamanlayıcı senaryosu ile sistemin çalıştırılarak gözlemlenmesiyle doğrulanabilir."
    },
    {
      "requirement_id": "KMU-003",
      "methods": [
        "Test"
      ],
      "rationale": "Art arda 5 başarısız giriş denemesi sonrası hesap kilitlenmesi ve 30 dakikalık kilit süresinin, sisteme girdi verilerek ve sonuçların gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "KMU-004",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut limiti (10 MB) ve adet limiti (5 dosya) kısıtlarının uygulanıp uygulanmadığı, farklı senaryolarla sistemin çalıştırılarak ve girdi verilerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-005",
      "methods": [
        "Test"
      ],
      "rationale": "Benzersiz takip numarası üretimi ve e-posta bildirimi işleminin, bir başvuru tamamlanarak sistemin çalıştırılması ve çıktıların gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "KMU-006",
      "methods": [
        "Test"
      ],
      "rationale": "Taslak kaydetme ve 30 gün içinde kaldığı yerden devam etme işlevinin, sistemin çalıştırılarak ve zamanlama senaryoları ile gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "WCAG 2.1 AA uyumluluğunun, kullanıcı arayüzü kodunun, yapılandırmasının ve erişilebilirlik araçlarının çıktılarının gözle denetlenerek (inceleme) doğrulanması gerekir."
    },
    {
      "requirement_id": "KMU-008",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Verilerin yalnızca Türkiye sınırları içindeki sunucularda saklanmasının, altyapı yapılandırma belgeleri ve sunucu konum ayarlarının gözle denetlenerek (inceleme) doğrulanması gerekir."
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-MED-006-01",
      "title": "Verification of AES-256 encryption for stored casualty data",
      "covers": [
        "MED-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is installed on the tablet and a session is active.",
      "test_inputs": "A valid casualty record containing unique identifiers and medical data.",
      "assumptions": "The test environment allows direct access to the device's internal storage files for inspection.",
      "steps": [
        {
          "no": 1,
          "action": "Create a new casualty record with specific unique data (e.g., Name: 'Test_Patient', ID: '12345') via the application UI.",
          "expected": "The record is saved successfully and appears in the casualty list."
        },
        {
          "no": 2,
          "action": "Locate the storage file(s) containing the casualty data on the device file system.",
          "expected": "The file(s) exist and are accessible."
        },
        {
          "no": 3,
          "action": "Inspect the raw content of the storage file(s) using a hex editor or file viewer.",
          "expected": "The raw content does not contain the plaintext values 'Test_Patient' or '12345'."
        },
        {
          "no": 4,
          "action": "Verify the encryption algorithm used for the storage files via the application's security configuration or system logs.",
          "expected": "The configuration or logs confirm that AES-256 is the active encryption standard for local storage."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Macro-averaged F1 score verification on held-out set",
      "covers": [
        "AI-002"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and ready for evaluation. The held-out evaluation set is available and labeled.",
      "test_inputs": "The held-out evaluation dataset.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Run the classification model on the held-out evaluation set.",
          "expected": "The model generates predictions for all documents in the set without errors."
        },
        {
          "no": 2,
          "action": "Calculate the macro-averaged F1 score comparing predictions to ground truth labels.",
          "expected": "The calculated macro-averaged F1 score is at least 0.90."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Recall parity between Turkish and English documents",
      "covers": [
        "AI-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained. The held-out evaluation set contains a sufficient number of documents labeled as Turkish and English.",
      "test_inputs": "The held-out evaluation dataset filtered by language (Turkish and English).",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Run the classification model on the Turkish subset of the held-out evaluation set.",
          "expected": "Predictions are generated for all Turkish documents."
        },
        {
          "no": 2,
          "action": "Calculate the recall score for the Turkish subset.",
          "expected": "A recall value (R_tr) is obtained."
        },
        {
          "no": 3,
          "action": "Run the classification model on the English subset of the held-out evaluation set.",
          "expected": "Predictions are generated for all English documents."
        },
        {
          "no": 4,
          "action": "Calculate the recall score for the English subset.",
          "expected": "A recall value (R_en) is obtained."
        },
        {
          "no": 5,
          "action": "Calculate the absolute difference between R_tr and R_en.",
          "expected": "The absolute difference is less than or equal to 5 percentage points."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Kullanıcı arayüzünün WCAG 2.1 AA uyumluluğunun davranışsal doğrulanması",
      "covers": [
        "KMU-007"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Erişilebilirlik özellikleri etkin olan bir ekran okuyucu (ör. NVDA veya JAWS) yüklüdür.",
      "test_inputs": "Klavye ve ekran okuyucu girdileri.",
      "assumptions": "Sistemde WCAG 2.1 AA kontrol listesi ve ekran okuyucu uyumlu test senaryoları hazır kabul edilir.",
      "steps": [
        {
          "no": 1,
          "action": "Kullanıcı arayüzüne klavye ile gezinilir ve tüm etkileşimli öğelere (butonlar, giriş alanları, menüler) Tab tuşu ile erişilir.",
          "expected": "Odak sırası mantıklıdır, odak göstergesi görülebilir ve tüm işlevler klavye ile tamamlanabilir."
