        {
          "no": 2,
          "action": "Ekran okuyucu ile sayfa içeriği taranır.",
          "expected": "Başlıklar, etiketler ve alt metinler doğru okunur; görseller için uygun alternatif metinler sağlanır."
        },
        {
          "no": 3,
          "action": "Sayfa içeriği %200 oranında yakınlaştırılır.",
          "expected": "İçerik kaybolmaz, taşma olmaz ve tüm işlevler kullanılmaya devam edilebilir."
        }
      ]
