{
  "test_cases": [
    {
      "id": "TC-AI-004-01",
      "title": "95th percentile latency under load",
      "covers": [
        "AI-004"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The service is deployed in a performance test environment.",
      "test_inputs": "A load generator configured to send 50 requests per second for a sufficient duration to collect at least 20 requests for percentile calculation.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Initiate a load test sending 50 requests per second to the classification endpoint.",
          "expected": "The service accepts all requests and begins processing."
        },
        {
          "no": 2,
          "action": "Allow the load test to run until at least 20 requests have been completed to calculate the 95th percentile.",
          "expected": "The 95th percentile of the response times for the completed requests is less than or equal to 500 ms."
        }
      ]
    },
    {
      "id": "TC-AI-005-01",
      "title": "Verification of audit log fields for a single request",
      "covers": [
        "AI-005"
      ],
